def lcs(A, B):
    rows = len(A) + 1
    cols = len(B) + 1

    # Init matrix with 0s
    dp = [[0 for _ in range(cols)] for _ in range(rows)]

    for i in range(1, rows):
        for j in range(1, cols):
            if A[i - 1] == B[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])

    return dp[rows - 1][cols - 1]

print(lcs("ABCDGH", "AEDFHR"))
